  sealed class Api:IConversationApi {public IList<ChatMessage> Seen;public readonly List<IList<ChatMessage>> Requests=new List<IList<ChatMessage>>();public int Descriptions;public string Description="fallback observation";public TaskCompletionSource<bool> DescriptionEntered,DescriptionResume;public async Task<string> ChatAsync(ConnectionSettings s,IList<ChatMessage> m,CancellationToken c){if(s.Model=="vision"){Descriptions++;if(DescriptionEntered!=null){DescriptionEntered.TrySetResult(true);await DescriptionResume.Task;}return new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new[]{Description});}Seen=m.Select(x=>x.Copy()).ToList();Requests.Add(Seen);return "answer";}public Task<string> TranscribeAsync(ConnectionSettings s,byte[] b,CancellationToken c){return Task.FromResult("");}public Task<byte[]> SpeechAsync(ConnectionSettings s,string v,string t,CancellationToken c){return Task.FromResult(new byte[0]);}public void Dispose(){}}
