  sealed class Provider:IDisposable {readonly HttpListener listener=new HttpListener();public readonly List<string> Bodies=new List<string>();public readonly Task Done;public string Url;public Provider(int count){var socket=new TcpListener(IPAddress.Loopback,0);socket.Start();int port=((IPEndPoint)socket.LocalEndpoint).Port;socket.Stop();Url="http://127.0.0.1:"+port+"/";listener.Prefixes.Add(Url);listener.Start();Done=Task.Run(async delegate{for(int i=0;i<count;i++){var context=await listener.GetContextAsync();using(var reader=new StreamReader(context.Request.InputStream))Bodies.Add(await reader.ReadToEndAsync());byte[] data=Encoding.UTF8.GetBytes("{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":\"summary or answer\"},\"finish_reason\":\"stop\"}]}");context.Response.ContentType="application/json";context.Response.ContentLength64=data.Length;await context.Response.OutputStream.WriteAsync(data,0,data.Length);context.Response.Close();}});}public void Dispose(){listener.Stop();listener.Close();}}
  static void Check(bool value,string message){if(!value)throw new Exception(message);}
  static int EventCount(ProactiveEventStore s){var type=typeof(ProactiveEventStore);var gate=type.GetField("gate",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(s);lock(gate)return ((System.Collections.IDictionary)type.GetField("events",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(s)).Count;}
