   var shared=new ProactiveEventStore();var firstSession=new ConversationSession(new Api(),new Speech(),()=>null);var secondSession=new ConversationSession(new Api(),new Speech(),()=>null);firstSession.ProactiveEvents=shared;secondSession.ProactiveEvents=shared;firstSession.SelectPersona("pet1");secondSession.SelectPersona("pet2");firstSession.AttachProactive(new ProactiveEvent("shared1","pet1","a",new byte[]{137,80,78,71,0,0,0,0},DateTime.UtcNow,"a",null));secondSession.AttachProactive(new ProactiveEvent("shared2","pet2","b",new byte[]{137,80,78,71,0,0,0,0},DateTime.UtcNow,"b",null));firstSession.Clear();firstSession.Dispose();Check(shared.TryGet("shared2").Png!=null,"closing one session preserves another companion's shared context");secondSession.Dispose();shared.Dispose();
   var directory=Path.Combine(Path.GetTempPath(),"proactive-history-"+Guid.NewGuid().ToString("N"));var history=new HistoryStore(directory);var api2=new Api();using(var active=new ConversationSession(api2,new Speech(),()=>null,history)){active.SelectPersona("pet");active.AttachProactive(new ProactiveEvent("persist","pet","saved original",new byte[]{137,80,78,71,0,0,0,0},DateTime.UtcNow,"window",null,"private observation"));Check(!Directory.Exists(directory)||Directory.GetFiles(directory).Length==0,"attachment alone does not persist history");var settings=new PetSettings{AgentEnabled=false,ReadReplies=false,Text=new ConnectionSettings{BaseUrl="http://127.0.0.1:9001/v1",Model="chat",ImageSupport=CapabilitySupport.Supported}};active.SendTextAsync("reply",settings,"pet").GetAwaiter().GetResult();active.FlushHistoryAsync().GetAwaiter().GetResult();Check(!active.ExportHistory().Contains("private observation"),"export excludes transient observation");}using(var fresh=new ConversationSession(new Api(),new Speech(),()=>null,new HistoryStore(directory))){fresh.SelectPersona("pet");Check(fresh.History.Messages.Count==3 && fresh.History.ForRequest("","next").Any(m=>m.Content=="saved original") && fresh.History.Messages.All(m=>!m.Content.Contains("private observation")&&(m.Attachments==null||m.Attachments.Count==0)),"encrypted restart preserves only genuine text and restores projection");}
   directory=Path.Combine(Path.GetTempPath(),"proactive-close-"+Guid.NewGuid().ToString("N"));using(var active=new ConversationSession(new Api(),new Speech(),()=>null,new HistoryStore(directory))){active.SelectPersona("pet");active.AttachProactive(new ProactiveEvent("unanswered","pet","unanswered text",null,DateTime.UtcNow,"window",null));active.SaveHistoryForCloseAsync().GetAwaiter().GetResult();Check(!Directory.Exists(directory)||Directory.GetFiles(directory).Length==0,"close does not create unanswered chat file");}using(var fresh=new ConversationSession(new Api(),new Speech(),()=>null,new HistoryStore(directory))){fresh.SelectPersona("pet");Check(fresh.History.Messages.Count==0,"unanswered message does not survive close and restart");fresh.AttachProactive(new ProactiveEvent("accepted","pet","accepted text",null,DateTime.UtcNow,"window",null));var settings=new PetSettings{AgentEnabled=false,ReadReplies=false,Text=new ConnectionSettings{BaseUrl="http://127.0.0.1:9001/v1",Model="chat",ImageSupport=CapabilitySupport.Supported}};fresh.SendTextAsync("real reply",settings,"pet").GetAwaiter().GetResult();fresh.SaveHistoryForCloseAsync().GetAwaiter().GetResult();}using(var fresh=new ConversationSession(new Api(),new Speech(),()=>null,new HistoryStore(directory))){fresh.SelectPersona("pet");Check(fresh.History.Messages.Count==3 && fresh.History.Messages[0].Content=="accepted text","admitted reply persists original proactive message across close");}
   directory=Path.Combine(Path.GetTempPath(),"proactive-close-existing-"+Guid.NewGuid().ToString("N"));using(var active=new ConversationSession(new Api(),new Speech(),()=>null,new HistoryStore(directory))){active.SelectPersona("pet");active.History.Commit("existing question","existing answer");active.AttachProactive(new ProactiveEvent("unanswered2","pet","unanswered text",null,DateTime.UtcNow,"window",null));active.SaveHistoryForCloseAsync().GetAwaiter().GetResult();}using(var fresh=new ConversationSession(new Api(),new Speech(),()=>null,new HistoryStore(directory))){fresh.SelectPersona("pet");Check(fresh.History.Messages.Count==2 && fresh.History.Messages[0].Content=="existing question","close preserves earlier ordinary history without unanswered proactive text");}
   directory=Path.Combine(Path.GetTempPath(),"proactive-synthetic-live-"+Guid.NewGuid().ToString("N"));using(var active=new ConversationSession(new Api(),new Speech(),()=>null,new HistoryStore(directory))){active.SelectPersona("pet");active.AttachProactive(new ProactiveEvent("liveblank","pet","unanswered text",null,DateTime.UtcNow,"window",null));active.AddLiveTurn("pet","","live output");active.SaveHistoryForCloseAsync().GetAwaiter().GetResult();}using(var fresh=new ConversationSession(new Api(),new Speech(),()=>null,new HistoryStore(directory))){fresh.SelectPersona("pet");Check(fresh.History.Messages.All(m=>m.Source!="proactive"),"synthetic live placeholder does not accept proactive message");}
   Console.WriteLine("Proactive conversation tests passed");return 0;
  }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 }
